#define ISOM_BOX_IMPL_DECL(a_name) \
                GF_Box * a_name##_box_new(); \
                void a_name##_box_del(GF_Box *); \
                GF_Err a_name##_box_read(GF_Box *s, GF_BitStream *bs); \
                GF_Err a_name##_box_write(GF_Box *s, GF_BitStream *bs); \
